package com.maintenance.maintenance_api.controller;

import com.maintenance.maintenance_api.dto.PredictionDto;
import com.maintenance.maintenance_api.service.PredictionService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

/**
 * PredictionController exposes ML predictions stored in PostgreSQL.
 * Strictly READ-ONLY (GET): predictions are generated by the external ML pipeline, not by Spring Boot.
 */
@RestController
@RequiredArgsConstructor
@Tag(name = "Predictions", description = "Consultation des prédictions de pannes générées par le pipeline ML (Lecture seule)")
public class PredictionController {

    private final PredictionService predictionService;

    @GetMapping("/api/predictions")
    @Operation(summary = "Lister toutes les prédictions enregistrées (avec filtres optionnels par composant et statut)")
    public ResponseEntity<List<PredictionDto>> getAllPredictions(
            @RequestParam(required = false) String component,
            @RequestParam(required = false) String status) {
        return ResponseEntity.ok(predictionService.getAllPredictions(component, status));
    }

    @GetMapping("/api/predictions/latest")
    @Operation(summary = "Récupérer la dernière prédiction pour chacune des machines")
    public ResponseEntity<List<PredictionDto>> getLatestPredictionsForAllMachines() {
        return ResponseEntity.ok(predictionService.getLatestPredictionsForAllMachines());
    }

    @GetMapping("/api/machines/{id}/predictions")
    @Operation(summary = "Récupérer l'historique de toutes les prédictions pour une machine")
    public ResponseEntity<List<PredictionDto>> getPredictionsByMachineId(@PathVariable Long id) {
        return ResponseEntity.ok(predictionService.getPredictionsByMachineId(id));
    }

    @GetMapping("/api/machines/{id}/predictions/latest")
    @Operation(summary = "Récupérer la dernière prédiction enregistrée pour une machine")
    public ResponseEntity<PredictionDto> getLatestPredictionByMachineId(@PathVariable Long id) {
        return ResponseEntity.ok(predictionService.getLatestPredictionByMachineId(id));
    }
}
